1import { useRef, useEffect } from "react";
2
3function Header({ query, onQueryChange }) {
4  const searchRef = useRef(null);
5
6  useEffect(function () {
7    searchRef.current.focus();
8  }, []);
9
10  function handleChange(e) {
11    onQueryChange(e.target.value);
12  }
13
14  function handleClear() {
15    onQueryChange("");
16    searchRef.current.focus();
17  }
18
19  return (
20    <header className="header">
21      <h2 className="title-primary">My Daily Journal</h2>
22      <p className="subtitle">Capture your thoughts, one day at a time.</p>
23      <div className="header-search">
24        <input
25          ref={searchRef}
26          className="search-input"
27          type="text"
28          placeholder="Search entries..."
29          value={query}
30          onChange={handleChange}
31        />
32        {query && (
33          <button className="btn-clear" onClick={handleClear}>Clear</button>
34        )}
35      </div>
36    </header>
37  );
38}
39
40export default Header;

1import { useState, useEffect } from "react";
2
3function useFetch(url) {
4  const [data, setData] = useState(null);
5  const [isLoading, setIsLoading] = useState(true);
6  const [error, setError] = useState(null);
7  const [refetchKey, setRefetchKey] = useState(0);
8
9  useEffect(function () {
10    async function fetchData() {
11      setIsLoading(true);
12      setError(null);
13      try {
14        const res = await fetch(url);
15        
16        if (!res.ok) {
17          throw new Error("Could not load data. Status: " + res.status);
18        }
19        const json = await res.json();
20        setData(json);
21        setIsLoading(false);
22      } catch (err) {
23        setError(err.message);
24        setIsLoading(false);
25      }
26    }
27    fetchData();
28  }, [url, refetchKey]);
29
30  function refetch() {
31    setRefetchKey(function (k) { return k + 1; });
32  }
33
34  return { data, isLoading, error, refetch };
35}
36
37export default useFetch;

1import { useState, useMemo } from "react";
2
3function useSearch(entries) {
4  const [query, setQuery] = useState("");
5
6  const filteredEntries = useMemo(function () {
7    if (!query.trim()) return entries;
8    const lower = query.toLowerCase();
9
10    return entries.filter(function (entry) {
11      return (
12        entry.title.toLowerCase().includes(lower) ||
13        entry.content.toLowerCase().includes(lower)
14      );
15    });
16  }, [entries, query]);
17
18  return { query, setQuery, filteredEntries };
19}
20
21export default useSearch;

1import { useState, useMemo } from "react";
2
3function usePagination(entries, pageSize) {
4  const [currentPage, setCurrentPage] = useState(1);
5
6  const totalPages = useMemo(function () {
7    return Math.ceil(entries.length / pageSize);
8  }, [entries, pageSize]);
9
10  const pagedEntries = useMemo(function () {
11    const start = (currentPage - 1) * pageSize;
12    return entries.slice(start, start + pageSize);
13  }, [entries, currentPage, pageSize]);
14
15  function handleNext() {
16    setCurrentPage(function (p) { return Math.min(p + 1, totalPages); });
17  }
18
19  function handlePrev() {
20    setCurrentPage(function (p) { return Math.max(p - 1, 1); });
21  }
22
23  function reset() {
24    setCurrentPage(1);
25  }
26
27  return { currentPage, pagedEntries, totalPages, handleNext, handlePrev, reset };
28}
29
30export default usePagination;

1import { useMemo } from "react";
2import Header from "../components/Header";
3import EntryCard from "../components/EntryCard";
4import useFetch from "../hooks/useFetch";
5import useSearch from "../hooks/useSearch";
6import usePagination from "../hooks/usePagination";
7
8const ENTRIES_PER_PAGE = 5;
9
10function HomePage() {
11  const { data, isLoading, error, refetch } = useFetch(
12    "https://api.programiz.pro/api/Demo/v1/journal-entries"
13  );
14
15  const entries = useMemo(function () {
16    if (!data) return [];
17    return data.map(function (post) {
18      return {
19        ...post,
20        date: new Date(post.date).toLocaleDateString("en-US", {
21          year: "numeric", month: "short", day: "numeric"
22        }).toUpperCase()
23      };
24    });
25  }, [data]);
26
27  const { query, setQuery, filteredEntries } = useSearch(entries);
28  const { currentPage, pagedEntries, totalPages, handleNext, handlePrev, reset } = usePagination(
29    filteredEntries,
30    ENTRIES_PER_PAGE
31  );
32
33  function handleQueryChange(newQuery) {
34    setQuery(newQuery);
35    reset();
36  }
37
38  return (
39    <div className="main-container">
40      <Header query={query} onQueryChange={handleQueryChange} />
41      <section className="entries-section">
42        <div className="entry-list-header">
43          <h3>Recent Entries</h3>
44          <span className="entry-count">{filteredEntries.length}</span>
45          {query && <span className="entry-count">{"of " + entries.length}</span>}
46          <button className="btn btn-secondary" onClick={refetch}>Refresh</button>
47        </div>
48        {isLoading ? (
49          <p className="loading-state">Loading entries...</p>
50        ) : error ? (
51          <div className="error-banner">
52            <p className="error-label">Something went wrong.</p>
53            <p className="error-detail">{error}</p>
54          </div>
55        ) : pagedEntries.length === 0 ? (
56          <p className="empty-state">No entries found.</p>
57        ) : (
58          pagedEntries.map((entry) => (
59            <EntryCard
60              key={entry.id}
61              id={entry.id}
62              title={entry.title}
63              date={entry.date}
64              content={entry.content}
65              author={entry.author}
66            />
67          ))
68        )}
69        {!isLoading && !error && totalPages > 1 && (
70          <div className="pagination">
71            <button className="btn btn-secondary" onClick={handlePrev} disabled={currentPage === 1}>Previous</button>
72            <span className="pagination-info">Page {currentPage} of {totalPages}</span>
73            <button className="btn btn-secondary" onClick={handleNext} disabled={currentPage === totalPages}>Next</button>
74          </div>
75        )}
76      </section>
77    </div>
78  );
79}
80
81export default HomePage;

